[ExtensionOf(classStr(RetailPricingEngine))]
internal final class GUPRetailPricingEngine_Extension
{
    private const str RetailPricingCacheScope = 'RetailPricingCacheScope';
}

Method.Source:
public static boolean useRetailPricing(SalesPurchLine _salesLine)
{
    boolean result = next useRetailPricing(_salesLine);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && _salesLine.TableId == tableNum(SalesLine))
    {
        SalesLine localSalesLine = _salesLine as SalesLine;
        SalesTable salesTable = localSalesLine.salesTable();
        RetailSalesTable retailSalesTable = salesTable.retailSalesTable();
        result = GUPParameters::asRetailSalesOrder();

        SysGlobalObjectCache c = new SysGlobalObjectCache();
        str cacheKey = RetailPricingEngine::getCacheKey(_salesLine);
        container cachedValue = c.find(RetailPricingCacheScope, [cacheKey]);
        c.insert(RetailPricingCacheScope, [cacheKey], [result]);
    }

    return result;
}

public static boolean useRetailPricingEngineForSalesOrder(SalesId _salesId)
{
    boolean ret = next useRetailPricingEngineForSalesOrder(_salesId);

    ret = ret || GUPParameters::asRetailSalesOrder();

    return ret;
}
